class Solution {
public:
    int longestRepeatingSubstring(string s) {
        int n = s.size();
        int low = 1, high = n - 1, res = 0;

        auto has_dup = [&](int len) -> bool {
            unordered_set<string_view> seen;
            string_view sv(s);
            for (int i = 0; i <= n - len; ++i) {
                string_view sub = sv.substr(i, len);
                if (seen.find(sub) != seen.end()) return true;
                seen.insert(sub);
            }
            return false;
        };

        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (has_dup(mid)) {
                res = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return res;
    }
};

class Solution {
    public int longestRepeatingSubstring(String s) {
        int n = s.length();
        int low = 1, high = n - 1, res = 0;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (hasDup(s, mid)) {
                res = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return res;
    }

    private boolean hasDup(String s, int len) {
        Set<String> seen = new HashSet<>();
        int n = s.length();
        for (int i = 0; i <= n - len; ++i) {
            String sub = s.substring(i, i + len);
            if (seen.contains(sub)) return true;
            seen.add(sub);
        }
        return false;
    }
}

var longestRepeatingSubstring = function(s) {
    const n = s.length;
    let low = 1, high = n - 1, res = 0;

    const hasDup = (len) => {
        const seen = new Set();
        for (let i = 0; i <= n - len; i++) {
            const sub = s.slice(i, i + len);
            if (seen.has(sub)) return true;
            seen.add(sub);
        }
        return false;
    };

    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        if (hasDup(mid)) {
            res = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return res;
};
